{"file_text":"/**
 * System-Assigned Managed Identity Example
 * 
 * System-assigned identities are tied to the lifecycle of the Azure resource.
 * When the resource is deleted, the identity is automatically deleted.
 * Best for: Single resource authentication scenarios
 */

import { ManagedIdentityCredential } from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";
import { BlobServiceClient } from "@azure/storage-blob";

// 1. CREATE CREDENTIAL FOR SYSTEM-ASSIGNED IDENTITY
// Simply instantiate without any parameters
const credential = new ManagedIdentityCredential();

// 2. USE WITH AZURE KEY VAULT
async function getSecretFromKeyVault() {
  const keyVaultUrl = "https://my-keyvault.vault.azure.net";
  const secretClient = new SecretClient(keyVaultUrl, credential);

  try {
    const secret = await secretClient.getSecret("my-secret-name");
    console.log(`Secret value: ${secret.value}`);
    return secret.value;
  } catch (error) {
    console.error("Error accessing Key Vault:", error);
    throw error;
  }
}

// 3. USE WITH AZURE BLOB STORAGE
async function uploadBlobToStorage() {
  const storageAccountUrl = "https://mystorageaccount.blob.core.windows.net";
  const blobServiceClient = new BlobServiceClient(storageAccountUrl, credential);

  try {
    const containerClient = blobServiceClient.getContainerClient("my-container");
    const blockBlobClient = containerClient.getBlockBlobClient("example.txt");

    const content = "Hello from Managed Identity!";
    await blockBlobClient.upload(content, content.length);

    console.log("Blob uploaded successfully");
  } catch (error) {
    console.error("Error uploading blob:", error);
    throw error;
  }
}

// 4. ERROR HANDLING EXAMPLE
async function handleManagedIdentityErrors() {
  try {
    const token = await credential.getToken("https://vault.azure.net/.default");
    console.log("Token acquired successfully");
    console.log(`Expires on: ${new Date(token.expiresOnTimestamp)}`);
  } catch (error: any) {
    if (error.code === "ManagedIdentityCredential") {
      console.error("Managed Identity is not available or not configured");
      console.error("Make sure:");
      console.error("1. You're running on an Azure resource (VM, App Service, Function, etc.)");
      console.error("2. System-assigned identity is enabled on the resource");
      console.error("3. The identity has the required RBAC permissions");
    } else {
      console.error("Unexpected error:", error.message);
    }
    throw error;
  }
}

// EXPORT FOR USE IN OTHER MODULES
export { credential, getSecretFromKeyVault, uploadBlobToStorage, handleManagedIdentityErrors };
