{"file_text":"/**
 * User-Assigned Managed Identity Example
 * 
 * User-assigned identities are independent resources that can be assigned to multiple Azure resources.
 * They persist even when the associated resources are deleted.
 * Best for: Shared identity across multiple resources, fine-grained access control
 */

import { ManagedIdentityCredential } from "@azure/identity";
import { CosmosClient } from "@azure/cosmos";
import { EventHubProducerClient } from "@azure/event-hubs";

// OPTION 1: Specify by Client ID (recommended)
const clientId = "12345678-1234-1234-1234-123456789abc";
const credentialByClientId = new ManagedIdentityCredential(clientId);

// OPTION 2: Specify by Resource ID (full ARM resource ID)
const resourceId = "/subscriptions/{subscription-id}/resourcegroups/{resource-group}/providers/Microsoft.ManagedIdentity/userAssignedIdentities/{identity-name}";
const credentialByResourceId = new ManagedIdentityCredential({
  resourceId: resourceId
});

// OPTION 3: Using options object with Client ID
const credentialWithOptions = new ManagedIdentityCredential({
  clientId: clientId
});

// 1. USE WITH AZURE COSMOS DB
async function queryCosmos() {
  const endpoint = "https://my-cosmos-account.documents.azure.com:443/";
  const cosmosClient = new CosmosClient({
    endpoint,
    aadCredentials: credentialByClientId
  });

  try {
    const database = cosmosClient.database("my-database");
    const container = database.container("my-container");

    const querySpec = {
      query: "SELECT * FROM c WHERE c.status = @status",
      parameters: [{ name: "@status", value: "active" }]
    };

    const { resources } = await container.items.query(querySpec).fetchAll();
    console.log(`Found ${resources.length} items`);
    return resources;
  } catch (error) {
    console.error("Error querying Cosmos DB:", error);
    throw error;
  }
}

// 2. USE WITH AZURE EVENT HUBS
async function sendEventToEventHub() {
  const fullyQualifiedNamespace = "my-eventhub-namespace.servicebus.windows.net";
  const eventHubName = "my-event-hub";

  const producer = new EventHubProducerClient(
    fullyQualifiedNamespace,
    eventHubName,
    credentialByClientId
  );

  try {
    const batch = await producer.createBatch();
    batch.tryAdd({ body: "Event from user-assigned managed identity" });

    await producer.sendBatch(batch);
    console.log("Event sent successfully");
  } catch (error) {
    console.error("Error sending event:", error);
    throw error;
  } finally {
    await producer.close();
  }
}

// 3. MULTIPLE USER-ASSIGNED IDENTITIES
// When a resource has multiple user-assigned identities, you MUST specify which one
interface IdentityConfig {
  keyVaultIdentity: string;
  storageIdentity: string;
  databaseIdentity: string;
}

class MultiIdentityService {
  private identities: Map<string, ManagedIdentityCredential>;

  constructor(config: IdentityConfig) {
    this.identities = new Map([
      ["keyvault", new ManagedIdentityCredential(config.keyVaultIdentity)],
      ["storage", new ManagedIdentityCredential(config.storageIdentity)],
      ["database", new ManagedIdentityCredential(config.databaseIdentity)]
    ]);
  }

  getCredential(service: string): ManagedIdentityCredential {
    const credential = this.identities.get(service);
    if (!credential) {
      throw new Error(`No credential configured for service: ${service}`);
    }
    return credential;
  }
}

// Example usage
const identityService = new MultiIdentityService({
  keyVaultIdentity: "11111111-1111-1111-1111-111111111111",
  storageIdentity: "22222222-2222-2222-2222-222222222222",
  databaseIdentity: "33333333-3333-3333-3333-333333333333"
});

// 4. ERROR HANDLING WITH USER-ASSIGNED IDENTITY
async function validateUserAssignedIdentity(clientId: string) {
  const credential = new ManagedIdentityCredential(clientId);

  try {
    const token = await credential.getToken("https://management.azure.com/.default");
    console.log("User-assigned identity is working correctly");
    console.log(`Token for client ID: ${clientId}`);
    return true;
  } catch (error: any) {
    console.error("User-assigned identity validation failed:");

    if (error.message?.includes("clientId")) {
      console.error("❌ The specified client ID may not exist or not be assigned to this resource");
      console.error(`   Client ID: ${clientId}`);
      console.error("   Check: Azure Portal → Resource → Identity → User assigned");
    } else if (error.message?.includes("IMDS")) {
      console.error("❌ Instance Metadata Service (IMDS) is not available");
      console.error("   Make sure you're running on an Azure resource that supports managed identity");
    } else {
      console.error(`❌ ${error.message}`);
    }

    return false;
  }
}

export {
  credentialByClientId,
  credentialByResourceId,
  queryCosmos,
  sendEventToEventHub,
  MultiIdentityService,
  validateUserAssignedIdentity
};
