{"file_text":"/**
 * Local Development Fallback Strategies
 * 
 * Managed Identity only works on Azure resources. For local development,
 * you need fallback authentication methods.
 */

import {
  ManagedIdentityCredential,
  DefaultAzureCredential,
  ChainedTokenCredential,
  AzureCliCredential,
  EnvironmentCredential,
  TokenCredential
} from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";

// STRATEGY 1: DefaultAzureCredential (RECOMMENDED)
// Automatically tries multiple authentication methods in order:
// 1. EnvironmentCredential (env vars)
// 2. WorkloadIdentityCredential (Kubernetes)
// 3. ManagedIdentityCredential (Azure resources)
// 4. AzureCliCredential (Azure CLI login)
// 5. AzurePowerShellCredential (Azure PowerShell login)
function createDefaultCredential(): TokenCredential {
  // Works in both Azure and local development
  return new DefaultAzureCredential();
}

// STRATEGY 2: ChainedTokenCredential (Custom Fallback Chain)
// Explicitly define the authentication priority
function createCustomChainCredential(): TokenCredential {
  return new ChainedTokenCredential(
    new ManagedIdentityCredential(), // Try managed identity first (in Azure)
    new AzureCliCredential(),        // Fall back to Azure CLI (local dev)
    new EnvironmentCredential()       // Fall back to env vars (CI/CD)
  );
}

// STRATEGY 3: Environment-Based Selection
function createEnvironmentAwareCredential(): TokenCredential {
  const isProduction = process.env.NODE_ENV === "production";
  const isAzure = process.env.AZURE_ENVIRONMENT === "true" || 
                  process.env.WEBSITE_INSTANCE_ID !== undefined; // App Service indicator

  if (isAzure || isProduction) {
    console.log("Using Managed Identity (Azure environment)");
    return new ManagedIdentityCredential();
  } else {
    console.log("Using Azure CLI (local development)");
    return new AzureCliCredential();
  }
}

// STRATEGY 4: Configuration-Based with User-Assigned Identity
interface CredentialConfig {
  managedIdentityClientId?: string;
  useLocalDevelopment?: boolean;
}

function createConfigurableCredential(config: CredentialConfig = {}): TokenCredential {
  if (config.useLocalDevelopment) {
    // Local development mode
    return new ChainedTokenCredential(
      new AzureCliCredential(),
      new EnvironmentCredential()
    );
  } else if (config.managedIdentityClientId) {
    // User-assigned managed identity
    return new ChainedTokenCredential(
      new ManagedIdentityCredential(config.managedIdentityClientId),
      new AzureCliCredential() // Fallback for local testing
    );
  } else {
    // Default: use system-assigned or DefaultAzureCredential
    return new DefaultAzureCredential();
  }
}

// PRACTICAL EXAMPLE: Key Vault Client with Fallback
class KeyVaultService {
  private client: SecretClient;
  private credential: TokenCredential;

  constructor(keyVaultUrl: string, managedIdentityClientId?: string) {
    // Use DefaultAzureCredential for automatic fallback
    if (managedIdentityClientId) {
      // User-assigned identity in Azure, falls back to Azure CLI locally
      this.credential = new ChainedTokenCredential(
        new ManagedIdentityCredential(managedIdentityClientId),
        new AzureCliCredential()
      );
    } else {
      // System-assigned identity in Azure, multiple fallbacks locally
      this.credential = new DefaultAzureCredential();
    }

    this.client = new SecretClient(keyVaultUrl, this.credential);
  }

  async getSecret(secretName: string): Promise<string> {
    try {
      const secret = await this.client.getSecret(secretName);
      return secret.value || "";
    } catch (error: any) {
      console.error(`Error retrieving secret '${secretName}':`, error.message);
      throw error;
    }
  }
}

// USAGE EXAMPLES

// Example 1: Simple DefaultAzureCredential (works everywhere)
async function example1() {
  const credential = new DefaultAzureCredential();
  const client = new SecretClient("https://my-vault.vault.azure.net", credential);
  await client.getSecret("my-secret");
}

// Example 2: Custom chain with explicit fallback
async function example2() {
  const credential = createCustomChainCredential();
  const client = new SecretClient("https://my-vault.vault.azure.net", credential);
  await client.getSecret("my-secret");
}

// Example 3: Environment-aware selection
async function example3() {
  const credential = createEnvironmentAwareCredential();
  const client = new SecretClient("https://my-vault.vault.azure.net", credential);
  await client.getSecret("my-secret");
}

// Example 4: Using the KeyVaultService wrapper
async function example4() {
  // In Azure: uses managed identity
  // Locally: uses Azure CLI
  const service = new KeyVaultService(
    "https://my-vault.vault.azure.net",
    process.env.MANAGED_IDENTITY_CLIENT_ID
  );
  const secretValue = await service.getSecret("database-password");
  console.log("Secret retrieved successfully");
}

// LOCAL DEVELOPMENT SETUP INSTRUCTIONS
console.log(`
LOCAL DEVELOPMENT SETUP:

1. Azure CLI (Recommended):
   az login
   az account set --subscription "Your Subscription Name"

2. Environment Variables (for EnvironmentCredential):
   - AZURE_CLIENT_ID
   - AZURE_TENANT_ID
   - AZURE_CLIENT_SECRET

3. Service Principal (CI/CD):
   az login --service-principal -u <app-id> -p <password> --tenant <tenant-id>

4. VS Code Azure Account Extension:
   - Install "Azure Account" extension
   - Sign in through VS Code

TESTING:
- Test locally with: NODE_ENV=development npm start
- Test production config: NODE_ENV=production AZURE_ENVIRONMENT=true npm start
`);

export {
  createDefaultCredential,
  createCustomChainCredential,
  createEnvironmentAwareCredential,
  createConfigurableCredential,
  KeyVaultService
};
