{"file_text":"/**
 * Common Pitfalls and Error Handling for Managed Identity
 */

import {
  ManagedIdentityCredential,
  DefaultAzureCredential,
  TokenCredential
} from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";

// PITFALL 1: Not checking if Managed Identity is enabled
// ❌ BAD: Assumes managed identity is available
async function badExample1() {
  const credential = new ManagedIdentityCredential();
  const client = new SecretClient("https://vault.azure.net", credential);

  // This will fail if managed identity is not enabled
  await client.getSecret("secret");
}

// ✅ GOOD: Test managed identity availability first
async function goodExample1() {
  const credential = new ManagedIdentityCredential();

  try {
    // Test token acquisition before using with SDK clients
    await credential.getToken("https://vault.azure.net/.default");
    console.log("✓ Managed Identity is available");

    const client = new SecretClient("https://vault.azure.net", credential);
    await client.getSecret("secret");
  } catch (error: any) {
    if (error.message?.includes("ManagedIdentityCredential")) {
      console.error("❌ Managed Identity not available. Enable it in Azure Portal → Resource → Identity");
      throw new Error("Managed Identity must be enabled on this Azure resource");
    }
    throw error;
  }
}

// PITFALL 2: Missing RBAC permissions
// Even with managed identity enabled, you need proper role assignments
async function handleRBACErrors() {
  const credential = new ManagedIdentityCredential();
  const keyVaultUrl = "https://my-vault.vault.azure.net";
  const client = new SecretClient(keyVaultUrl, credential);

  try {
    const secret = await client.getSecret("my-secret");
    return secret.value;
  } catch (error: any) {
    console.error("Error accessing Key Vault:", error.message);

    // Check for permission-related errors
    if (error.statusCode === 403 || error.code === "Forbidden") {
      console.error(`
❌ RBAC PERMISSION ERROR
   The managed identity doesn't have permission to access this Key Vault.

   FIX:
   1. Get the managed identity's Object ID:
      - Azure Portal → Your Resource → Identity → Object ID

   2. Grant access:
      az keyvault set-policy \\
        --name my-vault \\
        --object-id <identity-object-id> \\
        --secret-permissions get list

   OR use RBAC (recommended):
      az role assignment create \\
        --assignee <identity-object-id> \\
        --role "Key Vault Secrets User" \\
        --scope /subscriptions/{sub-id}/resourceGroups/{rg}/providers/Microsoft.KeyVault/vaults/my-vault
      `);
    }

    throw error;
  }
}

// PITFALL 3: Using wrong Client ID for user-assigned identity
// ❌ BAD: Using Object ID instead of Client ID
async function badExample3() {
  // Object ID looks like this: "12345678-90ab-cdef-1234-567890abcdef"
  // Client ID also looks like a GUID, but they're different!
  const objectId = "12345678-90ab-cdef-1234-567890abcdef"; // WRONG!
  const credential = new ManagedIdentityCredential(objectId);

  // This will fail silently or with confusing errors
}

// ✅ GOOD: Use the correct Client ID
async function goodExample3() {
  // Get Client ID from: Azure Portal → Managed Identity → Properties → Client ID
  const clientId = "abcdef12-3456-7890-abcd-ef1234567890"; // This is the Application ID
  const credential = new ManagedIdentityCredential(clientId);
  console.log("✓ Using correct Client ID");
}

// PITFALL 4: Not handling token refresh
// Token refresh is automatic, but be aware of timing
async function demonstrateTokenLifecycle() {
  const credential = new ManagedIdentityCredential();

  // Get initial token
  const token1 = await credential.getToken("https://vault.azure.net/.default");
  console.log(`Token expires: ${new Date(token1.expiresOnTimestamp)}`);

  // The credential automatically refreshes tokens before they expire
  // You don't need to manually refresh, but be aware:
  // - Tokens typically last 24 hours
  // - Refresh happens ~30 minutes before expiration
  // - Network issues during refresh can cause temporary failures

  // ✅ GOOD: SDK clients handle refresh automatically
  const client = new SecretClient("https://vault.azure.net", credential);
  // This works even after 24+ hours because credential refreshes tokens
  await client.getSecret("secret");
}

// PITFALL 5: Multiple user-assigned identities without specifying which one
async function badExample5() {
  // If your resource has multiple user-assigned identities assigned to it,
  // you MUST specify which one to use
  const credential = new ManagedIdentityCredential(); // ❌ Which identity?

  // This will fail or use a random identity
}

async function goodExample5() {
  // ✅ Explicitly specify the identity
  const clientId = process.env.MANAGED_IDENTITY_CLIENT_ID!;

  if (!clientId) {
    throw new Error("MANAGED_IDENTITY_CLIENT_ID environment variable is required");
  }

  const credential = new ManagedIdentityCredential(clientId);
  console.log(`✓ Using specific identity: ${clientId}`);
}

// PITFALL 6: Not handling network timeouts to IMDS
// The Instance Metadata Service (IMDS) can be slow or unavailable
async function handleIMDSTimeout() {
  const credential = new ManagedIdentityCredential();

  try {
    // Set a reasonable timeout
    const timeoutMs = 10000; // 10 seconds
    const timeoutPromise = new Promise((_, reject) => 
      setTimeout(() => reject(new Error("IMDS timeout")), timeoutMs)
    );

    const tokenPromise = credential.getToken("https://vault.azure.net/.default");

    const token = await Promise.race([tokenPromise, timeoutPromise]);
    console.log("✓ Token acquired successfully");
  } catch (error: any) {
    if (error.message === "IMDS timeout") {
      console.error("❌ IMDS endpoint is not responding. Possible causes:");
      console.error("   - Not running on an Azure resource");
      console.error("   - Network connectivity issues");
      console.error("   - IMDS endpoint is blocked by firewall/proxy");
    }
    throw error;
  }
}

// PITFALL 7: Wrong scope/audience for the token
async function demonstrateScopes() {
  const credential = new ManagedIdentityCredential();

  // Common Azure scopes (audiences):
  const scopes = {
    keyVault: "https://vault.azure.net/.default",
    storage: "https://storage.azure.com/.default",
    azureManagement: "https://management.azure.com/.default",
    database: "https://database.windows.net/.default",
    eventHubs: "https://eventhubs.azure.net/.default",
    serviceBus: "https://servicebus.azure.net/.default"
  };

  try {
    // ✅ Use the correct scope for your service
    const token = await credential.getToken(scopes.keyVault);
    console.log("✓ Token acquired for Key Vault");
  } catch (error: any) {
    // ❌ Using wrong scope will fail
    console.error("Make sure you're using the correct scope for your Azure service");
  }
}

// COMPREHENSIVE ERROR HANDLER
async function robustManagedIdentityUsage(
  keyVaultUrl: string,
  clientId?: string
) {
  let credential: TokenCredential;

  try {
    // Create credential
    if (clientId) {
      credential = new ManagedIdentityCredential(clientId);
      console.log(`Using user-assigned identity: ${clientId}`);
    } else {
      credential = new ManagedIdentityCredential();
      console.log("Using system-assigned identity");
    }

    // Test credential before using
    console.log("Testing managed identity...");
    const testToken = await credential.getToken("https://vault.azure.net/.default");
    console.log("✓ Managed identity is working");
    console.log(`  Token expires: ${new Date(testToken.expiresOnTimestamp)}`);

    // Use with SDK client
    const client = new SecretClient(keyVaultUrl, credential);
    const secret = await client.getSecret("my-secret");

    return secret.value;

  } catch (error: any) {
    console.error("\n❌ MANAGED IDENTITY ERROR\n");

    // Categorize and provide specific guidance
    if (error.message?.includes("ManagedIdentityCredential")) {
      console.error("Cause: Managed Identity not available");
      console.error("Fix: Enable managed identity on your Azure resource");
      console.error("     Azure Portal → Resource → Identity → System assigned: On");
    } else if (error.statusCode === 403) {
      console.error("Cause: Missing RBAC permissions");
      console.error("Fix: Grant the managed identity access to the Key Vault");
      console.error(`     az role assignment create --assignee <identity-id> --role "Key Vault Secrets User" --scope <vault-id>`);
    } else if (error.message?.includes("IMDS")) {
      console.error("Cause: Cannot reach Instance Metadata Service");
      console.error("Fix: Ensure you're running on an Azure resource");
    } else if (error.code === "ENOTFOUND" || error.code === "ECONNREFUSED") {
      console.error("Cause: Network connectivity issue");
      console.error("Fix: Check firewall rules and network configuration");
    } else {
      console.error(`Cause: ${error.message}`);
    }

    console.error(`\nFull error:`, error);
    throw error;
  }
}

// DEBUGGING HELPER
async function debugManagedIdentity(clientId?: string) {
  console.log("=== MANAGED IDENTITY DIAGNOSTICS ===\n");

  // Check environment
  console.log("Environment:");
  console.log(`  NODE_ENV: ${process.env.NODE_ENV || "not set"}`);
  console.log(`  WEBSITE_INSTANCE_ID: ${process.env.WEBSITE_INSTANCE_ID || "not set"} (App Service)`);
  console.log(`  MSI_ENDPOINT: ${process.env.MSI_ENDPOINT || "not set"} (Managed Identity endpoint)`);
  console.log();

  // Try to get token
  const credential = clientId 
    ? new ManagedIdentityCredential(clientId)
    : new ManagedIdentityCredential();

  try {
    console.log("Attempting to acquire token...");
    const token = await credential.getToken("https://management.azure.com/.default");
    console.log("✓ SUCCESS");
    console.log(`  Token acquired at: ${new Date()}`);
    console.log(`  Expires at: ${new Date(token.expiresOnTimestamp)}`);
    console.log(`  Token length: ${token.token.length} characters`);
  } catch (error: any) {
    console.log("✗ FAILED");
    console.log(`  Error: ${error.message}`);
    console.log(`  Code: ${error.code || "N/A"}`);
  }
}

export {
  goodExample1,
  handleRBACErrors,
  robustManagedIdentityUsage,
  debugManagedIdentity
};
