{"file_text":"/**
 * Complete Production-Ready Example
 * 
 * This example demonstrates a full application using managed identity
 * with proper error handling, fallback strategies, and best practices.
 */

import {
  ManagedIdentityCredential,
  DefaultAzureCredential,
  ChainedTokenCredential,
  AzureCliCredential,
  TokenCredential
} from "@azure/identity";
import { SecretClient } from "@azure/keyvault-secrets";
import { BlobServiceClient } from "@azure/storage-blob";
import { CosmosClient } from "@azure/cosmos";

// Configuration interface
interface AppConfig {
  environment: "development" | "staging" | "production";
  managedIdentityClientId?: string;
  keyVaultUrl: string;
  storageAccountUrl: string;
  cosmosEndpoint: string;
}

// Credential factory with intelligent fallback
class CredentialFactory {
  static create(config: AppConfig): TokenCredential {
    const isDevelopment = config.environment === "development";
    const isAzureEnvironment = process.env.WEBSITE_INSTANCE_ID !== undefined ||
                               process.env.MSI_ENDPOINT !== undefined;

    if (isDevelopment && !isAzureEnvironment) {
      console.log("🔧 Development mode: Using Azure CLI credential");
      return new ChainedTokenCredential(
        new AzureCliCredential(),
        new DefaultAzureCredential()
      );
    }

    if (config.managedIdentityClientId) {
      console.log(`🔐 Using user-assigned managed identity: ${config.managedIdentityClientId}`);
      return new ChainedTokenCredential(
        new ManagedIdentityCredential(config.managedIdentityClientId),
        new AzureCliCredential() // Fallback for local testing with service principal
      );
    }

    console.log("🔐 Using system-assigned managed identity");
    return new ManagedIdentityCredential();
  }
}

// Azure Services wrapper with managed identity
class AzureServices {
  private credential: TokenCredential;
  private config: AppConfig;
  private secretClient?: SecretClient;
  private blobServiceClient?: BlobServiceClient;
  private cosmosClient?: CosmosClient;

  constructor(config: AppConfig) {
    this.config = config;
    this.credential = CredentialFactory.create(config);
  }

  // Initialize and validate managed identity
  async initialize(): Promise<void> {
    console.log("Initializing Azure services...");

    try {
      // Test credential by acquiring a token
      const token = await this.credential.getToken("https://vault.azure.net/.default");
      console.log("✓ Managed identity validated");
