Missing Cosmos DB permission. Grant access with:
az cosmosdb sql role assignment create --account-name <account> --resource-group <rg> --role-definition-name "Cosmos DB Built-in Data Contributor" --principal-id <identity-object-id> --scope "/"
        `);
      }

      throw error;
    }
  }

