⚠️  INSTANCE METADATA SERVICE (IMDS) UNREACHABLE

This typically means:
1. Not running on an Azure VM/App Service/Function/Container
2. Network firewall blocking IMDS endpoint (169.254.169.254)
3. Running in a restricted network environment

For local development, make sure you're logged in:
az login
az account set --subscription "<your-subscription>"
      `);
    }
  }

  // Helper: Convert stream to string
  private async streamToString(readableStream: NodeJS.ReadableStream): Promise<string> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      readableStream.on("data", (data) => {
        chunks.push(data instanceof Buffer ? data : Buffer.from(data));
      });
      readableStream.on("end", () => {
        resolve(Buffer.concat(chunks).toString("utf8"));
      });
      readableStream.on("error", reject);
    });
  }
